('name-effect-sigil-damascus', 'Damascus Fold', 'Folded steel cut into the letters: hairline waves, a cold silver ridge, and a darkened valley like a finished blade.', 'name_effect', 'data:,', NULL, 0, 560, NULL, NULL, NULL, 'sigil-damascus', 'legendary', 6200, TRUE),
