('name-effect-sigil-porcelain', 'Porcelain Craze', 'Warm glaze with two gold hairline cracks. The letters stay a solid cup color, the crazing does not punch through.', 'name_effect', 'data:,', NULL, 0, 400, NULL, NULL, NULL, 'sigil-porcelain', 'epic', 6203, TRUE),
('name-effect-sigil-filigree', 'Crimson Filigree', 'Wine ground, a gold mid band, and three fixed sparks set like engraved metalwork on the name.', 'name_effect', 'data:,', NULL, 0, 540, NULL, NULL, NULL, 'sigil-filigree', 'legendary', 6204, TRUE),
